INSERT INTO public.periods (id,label_fr,label_en,description_fr,description_en,wikidata_id,wikipedia_title_fr,wikipedia_title_en,start_date,end_date,start_years_bp,end_years_bp,non_thematic) VALUES
('12be7cc5-4350-4b9f-aa1a-cde0e147419c','De la Grande Alliance aux deux blocs','From the Grand Alliance to two blocs','À Yalta, les Alliés négocient encore ensemble ; les désaccords sur l’Europe, la division de l’Allemagne et la guerre de Corée creusent ensuite le fossé entre Washington et Moscou.','The Allies still negotiate together at Yalta; disputes over Europe, the division of Germany and the Korean War then deepen the rift between Washington and Moscow.',NULL,NULL,NULL,'1945-02-04','1955-05-14',81.7645448323066,71.4948665297741,false),
('b2212510-4206-4000-ae22-2c8b47d7443a','Crises des blocs et détente','Bloc confrontations and détente','Berlin et Cuba mettent les blocs face à face ; tandis que la guerre s’intensifie au Vietnam et que les non-alignés s’organisent, Washington et Moscou négocient des limites à leurs arsenaux.','Berlin and Cuba bring the blocs face to face; as the war in Vietnam escalates and non-aligned states organise, Washington and Moscow negotiate limits on their arsenals.',NULL,NULL,NULL,'1955-05-14','1975-08-01',71.4948665297741,51.2785763175907,false),
('ba855a2e-1af1-4856-8219-95392657a103','De la détente au regain des tensions','From détente to renewed tensions','Les engagements d’Helsinki offrent un point d’appui aux dissidents ; la guerre en Afghanistan et la crise des euromissiles ravivent les tensions entre les blocs.','The Helsinki commitments give dissidents a point of reference; the war in Afghanistan and the Euromissile crisis sharpen tensions between the blocs.',NULL,NULL,NULL,'1975-08-01','1985-03-11',51.2785763175907,41.668720054757,false),
('2cea90d2-c74b-491f-beea-7927c148cb99','Réformes soviétiques et fin des blocs','Soviet reforms and the end of the blocs','Les réformes de Gorbatchev et la reprise du désarmement accompagnent les révolutions en Europe de l’Est, la réunification allemande et la dissolution de l’URSS.','Gorbachev’s reforms and renewed arms reductions accompany revolutions in Eastern Europe, German reunification and the dissolution of the Soviet Union.',NULL,NULL,NULL,'1985-03-11','1991-12-26',41.668720054757,34.8761122518823,false),
('8123038c-d61a-4f30-890f-de66ef22c906','Blocus de Berlin','Berlin Blockade','L’URSS coupe les accès terrestres et fluviaux aux secteurs occidentaux de Berlin, que les Alliés occidentaux ravitaillent par un pont aérien.','The Soviet Union cuts land and water access to the western sectors of Berlin, which the Western Allies supply by air.','Q151349','Blocus de Berlin','Berlin Blockade','1948-06-24','1949-05-12',78.3805612594114,77.4989733059548,false);
INSERT INTO public.events (id,label_fr,label_en,description_fr,description_en,wikidata_id,wikipedia_title_fr,wikipedia_title_en,date,date_years_bp) VALUES
('77f4599c-c54f-4f60-b40e-958a9ff79770','Truman expose sa doctrine au Congrès','Truman outlines his doctrine to Congress','Harry Truman demande une aide pour la Grèce et la Turquie et engage les États-Unis à soutenir les peuples qu’il estime menacés de subordination.','Harry Truman asks Congress to aid Greece and Turkey and pledges US support for peoples he considers threatened with subjugation.',NULL,NULL,NULL,'1947-03-12',79.6673511293635),
('611fc887-ef46-474b-a1c6-43fa897fcc1f','Traité de l’Atlantique nord','North Atlantic Treaty','Douze pays d’Europe et d’Amérique du Nord signent à Washington le traité de défense collective qui fonde l’OTAN.','Twelve European and North American countries sign the collective defence treaty in Washington that establishes NATO.','Q877399','Traité de l''Atlantique nord','North Atlantic Treaty','1949-04-04',77.6030116358658),
('1ec385cb-caca-4832-bf9c-c753f4f7545d','Signature du pacte de Varsovie','Signing of the Warsaw Pact','L’URSS et sept États d’Europe de l’Est concluent une alliance militaire après l’entrée de la République fédérale d’Allemagne dans l’OTAN.','The Soviet Union and seven Eastern European states form a military alliance after West Germany joins NATO.',NULL,NULL,NULL,'1955-05-14',71.4948665297741),
('9644ac86-5064-4655-8a45-7484370dad73','Début du soulèvement de Budapest','Budapest uprising begins','Une manifestation étudiante à Budapest devient un soulèvement contre le régime ; une intervention soviétique l’écrase en novembre.','A student demonstration in Budapest develops into an uprising against the regime; Soviet intervention crushes it in November.',NULL,NULL,NULL,'1956-10-23',70.0492813141684),
('b6a26f65-687d-48f4-896c-9185062a119e','Début de la construction du mur de Berlin','Construction of the Berlin Wall begins','Les autorités est-allemandes ferment la frontière entre les secteurs de Berlin et commencent à installer les barrières qui deviendront le mur.','East German authorities seal the border between the sectors of Berlin and begin installing the barriers that will become the Wall.',NULL,NULL,NULL,'1961-08-13',65.2443531827515),
('99bb9a8a-c59e-495c-b3d7-e06c225fcf44','Les troupes du pacte de Varsovie entrent en Tchécoslovaquie','Warsaw Pact troops enter Czechoslovakia','Dans la nuit du 20 au 21 août, des troupes conduites par l’URSS franchissent la frontière pour mettre fin aux réformes du Printemps de Prague.','On the night of 20–21 August, Soviet-led troops cross the border to halt the Prague Spring reforms.',NULL,NULL,NULL,'1968-08-20',58.2245037645448),
('1ec51f6d-9147-4ca4-8e99-b518da6d492a','Signature des accords SALT I','SALT I agreements signed','À Moscou, Nixon et Brejnev signent le traité sur les défenses antimissiles et un accord provisoire limitant certains lanceurs stratégiques offensifs.','In Moscow, Nixon and Brezhnev sign the Anti-Ballistic Missile Treaty and an interim agreement limiting certain offensive strategic launchers.',NULL,NULL,NULL,'1972-05-26',54.4599589322382),
('2387d31a-1cd7-47be-8d34-92d0b837def8','Entrée des troupes soviétiques en Afghanistan','Soviet troops enter Afghanistan','L’URSS intervient militairement pour maintenir à Kaboul un pouvoir allié, engageant ses forces dans une guerre qui dure près de dix ans.','The USSR intervenes to keep an allied government in Kabul, committing its forces to a war that lasts nearly a decade.',NULL,NULL,NULL,'1979-12',46.9445585215606),
('640dfa78-75ab-4ad1-a06b-511bd99504e5','Accord de Gdańsk','Gdańsk Agreement','Au terme des grèves du littoral polonais, les autorités acceptent le principe de syndicats indépendants, ouvrant la voie à Solidarność.','Following strikes on the Polish coast, the authorities accept independent trade unions, paving the way for Solidarity.',NULL,NULL,NULL,'1980-08-31',46.1943874058864),
('b3e99e6d-3375-4eff-9cde-9107964bec95','Gorbatchev à la tête du Parti communiste soviétique','Gorbachev becomes Soviet Communist Party leader','Le Comité central choisit Mikhaïl Gorbatchev comme secrétaire général ; il engagera les réformes connues sous les noms de perestroïka et de glasnost.','The Central Committee elects Mikhail Gorbachev general secretary; he will pursue the reforms known as perestroika and glasnost.',NULL,NULL,NULL,'1985-03-11',41.668720054757),
('a9c27759-5da9-439b-9b26-030c07443c24','Traité sur les forces nucléaires à portée intermédiaire','Intermediate-Range Nuclear Forces Treaty','À Washington, Reagan et Gorbatchev signent un traité qui prévoit l’élimination de toute une catégorie de missiles terrestres américains et soviétiques.','In Washington, Reagan and Gorbachev sign a treaty providing for the elimination of an entire class of US and Soviet ground-launched missiles.','Q169401','Traité sur les forces nucléaires à portée intermédiaire','Intermediate-Range Nuclear Forces Treaty','1987-12-08',38.9253935660507),
('446fa502-a885-4e19-a026-3e3cd04421b2','Fin du retrait soviétique d’Afghanistan','Soviet withdrawal from Afghanistan completed','Les dernières troupes soviétiques quittent l’Afghanistan conformément au calendrier des accords de Genève ; la guerre dans le pays se poursuit.','The last Soviet troops leave Afghanistan on the timetable agreed in Geneva; the war in the country continues.',NULL,NULL,NULL,'1989-02-15',37.7344284736482),
('444ba1d2-c342-4feb-a84f-d1b26f0d8850','Réunification allemande','German reunification','La République démocratique allemande rejoint la République fédérale d’Allemagne ; Berlin redevient la capitale du pays réuni.','The German Democratic Republic joins the Federal Republic of Germany; Berlin becomes the capital of the reunited country.','Q56039','Réunification allemande','German reunification','1990-10-03',36.1054072553046);
